package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.model.OwnerIdentity;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;

/**
 * The single duplicate check on create, keyed on the owner's full identity — the
 * {@code normalizedTelephone|email|householdId} composite defined by {@link OwnerIdentity}.
 * Only an existing owner with the same identity is a hard duplicate, rejected 409 via
 * {@link DuplicateOwnerException}. Two owners sharing a household (same lastName and postcode)
 * but differing in telephone or email are therefore <em>not</em> a hard duplicate: they may
 * coexist as household members — which is what makes the household membership-level ceiling
 * meaningful — and are instead soft-flagged downstream by {@link AssignPossibleDuplicate}.
 *
 * <p>{@code sharesHousehold} bypasses this block entirely: a declared household member is always
 * allowed (and is not flagged as a possible duplicate downstream). Runs after the householdId is
 * assigned and before the owner is saved.
 */
public class EnsureUniqueOwnerIdentity {

    public void service(@Val Owner owner, @Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateOwnerException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return; // declared household member bypasses the duplicate block
        }
        String identity = OwnerIdentity.of(owner);
        for (Owner existing : ownerRepository.findAll()) {
            if (Boolean.TRUE.equals(existing.getDeleted())) {
                continue; // soft-deleted owners do not block a create
            }
            if (identity.equals(OwnerIdentity.of(existing))) {
                throw new DuplicateOwnerException(identity);
            }
        }
    }
}

package org.springframework.samples.petclinic.rest.escalation;

/**
 * Thrown when creating an owner whose <em>identity</em> — the
 * {@code normalizedTelephone|email|householdId} composite (see
 * {@code org.springframework.samples.petclinic.model.OwnerIdentity}) — already belongs to
 * another owner. Owners sharing only a household (same lastName and postcode) but differing in
 * telephone or email are <em>not</em> duplicates and may coexist as household members; only a
 * full identity match is rejected. Setting {@code sharesHousehold} bypasses this check (the new
 * owner is created as a declared household member). Handled globally by
 * {@link DuplicateOwnerExceptionHandler}, which responds 409.
 */
public class DuplicateOwnerException extends Exception {

    private final String identityKey;

    public DuplicateOwnerException(String identityKey) {
        super("An owner with the same identity already exists");
        this.identityKey = identityKey;
    }

    /** The identityKey that is already in use. */
    public String getIdentityKey() {
        return this.identityKey;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * The single definition of household identity, used by {@link AssignOwnerHousehold} (which
 * stamps the householdId) and by the household-keyed rules (duplicate detection, household
 * size), so the rule lives in one place.
 *
 * <p>A household is keyed on {@code (lastName, postcode)}: two owners are in the same
 * household when their normalized lastName and postcode match. The householdId is therefore
 * <em>deterministic</em> — the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode} — so owners with the same lastName and
 * postcode share it automatically, with no lookup. lastName is normalized case-insensitively
 * with collapsed whitespace; the postcode is used as given (empty when absent).
 */
final class OwnerHousehold {

    private OwnerHousehold() {
    }

    /**
     * The deterministic householdId for the given lastName and postcode: the first 12 hex
     * characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. Owners with the
     * same lastName and postcode therefore compute the same householdId automatically.
     */
    static String householdId(String lastName, String postcode) {
        String input = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        return sha256Hex(input).substring(0, 12);
    }

    /**
     * The number of owners in the given household — those whose {@code householdId} matches.
     * A {@code null} householdId matches nothing. Used by the household-keyed rules so the
     * membership comparison lives in the same place as the identity that defines it.
     */
    static int memberCount(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return 0;
        }
        int count = 0;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                count++;
            }
        }
        return count;
    }

    /**
     * The highest {@code membershipLevel} among the existing owners in the given household —
     * those whose {@code householdId} matches — or {@code null} when the household has no
     * existing member with a level. A {@code null} householdId matches nothing. Used by the
     * level ceiling so a new owner cannot leapfrog their household's current maximum.
     */
    static Integer maxMembershipLevel(String householdId, Iterable<Owner> owners) {
        if (householdId == null) {
            return null;
        }
        Integer max = null;
        for (Owner owner : owners) {
            if (householdId.equals(owner.getHouseholdId())) {
                Integer level = owner.getMembershipLevel();
                if (level != null && (max == null || level > max)) {
                    max = level;
                }
            }
        }
        return max;
    }

    /** Lower-case hex SHA-256 of the UTF-8 bytes of {@code value}. */
    private static String sha256Hex(String value) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest(value.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(Character.forDigit((b >> 4) & 0xF, 16));
                sb.append(Character.forDigit(b & 0xF, 16));
            }
            return sb.toString();
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }

    /** Lower-case and collapse whitespace runs to a single space for comparison. */
    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Stamps the owner's {@code householdId} — the deterministic identifier derived from
 * {@code (lastName, postcode)} by {@link OwnerHousehold}. Every owner receives one, so owners
 * with the same lastName and postcode automatically share a household with no lookup or
 * back-fill. Runs after the owner is built and before the household-keyed rules (duplicate
 * detection) so the householdId is known when they run.
 *
 * <p>{@code sharesHousehold} no longer creates the link (the link is implicit in the hash); it
 * only bypasses the duplicate block in {@link EnsureUniqueOwnerIdentity}.
 */
public class AssignOwnerHousehold {

    public void service(@Val Owner owner) {
        owner.setHouseholdId(OwnerHousehold.householdId(owner.getLastName(), owner.getPostcode()));
    }
}

